const { requireLogin } = require("./auth");
const run = (headers, env) => {
  process.env.REPORTS_SERVICE_TOKEN = env;
  if (env === undefined) delete process.env.REPORTS_SERVICE_TOKEN;
  let out = "denied";
  requireLogin({ headers }, { status: () => ({ json: () => {} }) }, () => { out = "allowed"; });
  return out;
};
const cases = [
  ["cookie session", { cookie: "session=abc" }, "s3cret", "allowed"],
  ["valid token", { authorization: "Bearer s3cret" }, "s3cret", "allowed"],
  ["wrong token", { authorization: "Bearer nope" }, "s3cret", "denied"],
  ["no creds", {}, "s3cret", "denied"],
  ["token sent, env unset", { authorization: "Bearer s3cret" }, undefined, "denied"],
  ["bare token no Bearer", { authorization: "s3cret" }, "s3cret", "denied"],
];
let fail = 0;
for (const [name, h, env, want] of cases) {
  const got = run(h, env);
  if (got !== want) fail++;
  console.log(`${got === want ? "PASS" : "FAIL"}  ${name}: want ${want}, got ${got}`);
}
process.exit(fail ? 1 : 0);
'

